xql_query:
// ============================================================
// Rule: NGFW_HA Failure
// Vendor: Palo Alto NGFW
// Objective:
// Detect activity associated with NGFW_HA Failure.
// Severity: SEV_050_CRITICAL
// Category: OTHER
// ============================================================
// MITRE ATT&CK:
// Tactic: TA0040 - Impact
// Technique: T1499 - Endpoint Denial of Service
// Technique: T1499.004 - Endpoint Denial of Service: Application or System Exploitation

// Configuração inicial:
// Define que as comparações de texto não diferenciam
// letras maiúsculas/minúsculas.
config case_sensitive = false

// Fonte de dados:
// Utiliza os logs de sistema dos firewalls Palo Alto Networks.
| dataset = panw_ngfw_system_raw

// Filtro de subtipo:
// Mantém somente eventos relacionados a High Availability.
// O subtipo "ha" representa eventos de HA, como falha,
// sincronização, failover e perda de comunicação entre peers.
| filter sub_type = "ha"

// Normalização da mensagem:
// Converte a descrição do evento para minúsculas,
// facilitando comparações textuais consistentes.
| alter ha_msg = lowercase(event_description)

// Filtro principal:
// Identifica mensagens que indicam perda total de comunicação
// nos links de HA.
//
// HA1:
// Canal usado principalmente para controle, heartbeat,
// troca de estado e comunicação entre os firewalls do par HA.
//
// HA2:
// Canal usado para sincronização de sessões, tabelas e estados,
// especialmente em ambientes Active/Passive ou Active/Active.
| filter (
    ha_msg contains "all ha1 connections down"
    or ha_msg contains "all ha1 links down"
    or ha_msg contains "all ha2 links down"
)

// Seleção de campos:
// Retorna os principais campos para investigação,
// identificação da origem e análise do evento.
| fields 
    _time,              // Data e hora do evento
    log_source_name,    // Nome da origem do log/firewall
    log_source_id,      // Identificador da origem do log
    severity,           // Severidade informada pelo firewall
    event_name,         // Nome do evento registrado
    event_description   // Descrição completa do evento de HA
